subChunks.guidedPracticeStarterCode:
-- apprentices: 1=Alice, 2=Bjorn, 3=Cassia, 4=Dorian
-- completions: (app=1,q=1), (app=2,q=1), (app=2,q=2), (app=3,q=3)

-- Query A — apprentices who have completed at least one quest:
SELECT a.name FROM apprentices a
WHERE EXISTS (
  SELECT 1 FROM completions c WHERE c.apprentice_id = a.id
);

-- Query B — apprentices who have completed NO quests:
SELECT a.name FROM apprentices a
WHERE NOT EXISTS (
  SELECT 1 FROM completions c WHERE c.apprentice_id = a.id
);

-- Query C — same intent as B, but NOT IN.
-- If any completions.apprentice_id is NULL, this returns NOTHING.
SELECT a.name FROM apprentices a
WHERE a.id NOT IN (SELECT apprentice_id FROM completions);

-- Query D — apprentices who have completed only quests worth >= 200 XP:
SELECT a.name FROM apprentices a
WHERE EXISTS (
  SELECT 1 FROM completions c
  JOIN quests q ON q.id = c.quest_id
  WHERE c.apprentice_id = a.id AND q.xp_reward >= 200
);
